import openpyxl
from collections import Counter, defaultdict

wb = openpyxl.load_workbook("FCSummaryReport_20260730084420.xlsx", read_only=True, data_only=True)
ws = wb[wb.sheetnames[0]]
rows = ws.iter_rows(min_row=1, values_only=True)
headers = next(rows)
idx = {h: i for i, h in enumerate(headers)}

def norm_dash(s):
    if s is None: return ""
    s = str(s)
    s = s.replace("\u2013","-").replace("\u2014","-").replace(chr(150), "-")
    while "  " in s: s = s.replace("  "," ")
    return s.strip()

NCID_LIST = {
    "TTSH NCID WARD 3E ICU","TTSH NCID WARD 6F (ISO)","TTSH NCID WARD 7E (NEP)",
    "TTSH NCID WARD 7F (ISO)","TTSH NCID WARD 8E (NEP)","TTSH NCID WARD 8F (ISO)",
    "TTSH NCID WARD 11E (NEP)","TTSH NCID WARD 11F (COHORT)","TTSH NCID WARD 12E (COHORT)",
    "TTSH NCID WARD 14F (COHORT)",
}

def priority(status):
    s = norm_dash(status).upper()
    if "VOID" in s or "DELET" in s:
        return 99
    table = {
        "COMPLETED": 1, "ACKNOWLEDGEMENT BY OTHER MEANS": 2,
        "ATTEMPTED - VIRTUAL FC COMPLETED, PENDING SIGNATURE": 3,
        "ATTEMPTED - PATIENT/NOK DECLINES TO SIGN": 4,
        "ATTEMPTED - PATIENT IS UNABLE TO SIGN": 5,
        "ATTEMPTED - UNABLE TO COMPLETE": 6,
    }
    return table.get(s, 98)

FC_MODE_AH = "financial counselling - ah"
FC_MODE_DOWNTIME = "financial counselling - downtime"

all_rows = list(rows)
kept_mode = [r for r in all_rows if norm_dash(r[idx['FC Mode']]).upper() in (FC_MODE_AH.upper(), FC_MODE_DOWNTIME.upper())]
kept_cancel = [r for r in kept_mode if str(r[idx['Admission Status']]).strip().upper() != "CANCELLED"]

groups = defaultdict(list)
for r in kept_cancel:
    enc = str(r[idx['Encounter No']]).strip()
    groups[enc].append(r)

winners = {}
for enc, grp in groups.items():
    best = None
    for r in grp:
        pri = priority(r[idx['FC Status']])
        fcid = r[idx['FC ID']]
        try:
            fcid_val = float(fcid)
        except:
            fcid_val = fcid
        if best is None:
            best = (pri, fcid_val, r)
        else:
            bpri, bfcid, br = best
            if pri < bpri:
                best = (pri, fcid_val, r)
            elif pri == bpri:
                try:
                    if fcid_val > bfcid: best = (pri, fcid_val, r)
                except: pass
    winners[enc] = best[2]

ncid_count = 0
for enc, r in winners.items():
    admtype = str(r[idx['Admission Type']]).strip().upper()
    if admtype.startswith("ELECTIVE INPA"):
        poc = str(r[idx['Point Of Care']]).strip() if r[idx['Point Of Care']] else ""
        if poc in NCID_LIST:
            ncid_count += 1

print("EL encounters in configured NCID ward list:", ncid_count)
