import re

def check_file(fname):
    with open(fname, encoding="utf-8") as f:
        lines = f.readlines()

    proc_start = None
    proc_name = None
    dims = {}
    issues = []

    def flush():
        nonlocal dims, proc_name
        dims = {}

    for i, line in enumerate(lines, start=1):
        s = line.strip()
        m = re.match(r'^(Public|Private)?\s*(Sub|Function)\s+(\w+)', s, re.IGNORECASE)
        if m:
            proc_name = m.group(3)
            dims = {}
            continue
        if re.match(r'^End\s+(Sub|Function)', s, re.IGNORECASE):
            proc_name = None
            dims = {}
            continue
        if proc_name:
            dm = re.match(r'^Dim\s+(.+)$', s, re.IGNORECASE)
            if dm:
                # split on commas at top level (ignoring types), simplistic
                parts = dm.group(1).split(',')
                for p in parts:
                    p = p.strip()
                    nm = re.match(r'^(\w+)', p)
                    if nm:
                        name = nm.group(1).upper()
                        if name in dims:
                            issues.append((fname, proc_name, name, dims[name], i))
                        else:
                            dims[name] = i
    return issues

files = ["Helpers.bas", "FilterFileA.bas", "FilterFileB.bas", "DeduplicateEncounters.bas",
          "BuildOutput.bas", "MainMacro.bas", "FilePickerForm.bas", "ProgressForm.bas"]
all_issues = []
for f in files:
    all_issues.extend(check_file(f))

print("Duplicate Dim within same procedure:")
for iss in all_issues:
    print(" ", iss)
print("Total:", len(all_issues))
